<script lang="ts">import { navigate } from 'svelte-routing'; import { getOrders, getProducts } from '../data/store'; import type { Order, Product } from '../types'; let orders = $state<Order[]>([]); let products = $state<Product[]>([]); $effect(() => { Promise.all([getOrders(),getProducts()]).then(([savedOrders,savedProducts]) => { orders = savedOrders; products = savedProducts }) }); function itemName(order: Order): string { return products.find((product) => product.id === order.items[0]?.productId)?.name ?? 'Your items' }</script>
<section class="mx-auto max-w-5xl"><h1 class="text-3xl font-bold text-navy">My orders</h1><p class="mt-2 text-muted">Track deliveries and review your past purchases.</p><div class="mt-7 space-y-3">{#each orders as order (order.id)}<button onclick={() => navigate('/orders/' + order.id)} class="grid w-full gap-3 rounded-panel bg-card p-5 text-left ring-1 ring-line hover:ring-primary md:grid-cols-4"><div><p class="text-xs font-semibold text-muted">ORDER</p><p class="mt-1 font-bold text-navy">{order.id}</p></div><div><p class="text-xs font-semibold text-muted">ITEMS</p><p class="mt-1 text-sm text-navy">{itemName(order)} + {order.items.length - 1}</p></div><div><p class="text-xs font-semibold text-muted">TOTAL</p><p class="mt-1 font-bold text-navy">${order.total.toFixed(2)}</p></div><div><p class="text-xs font-semibold text-muted">STATUS</p><p class="mt-1 font-semibold text-success">{order.status}</p></div></button>{:else}<div class="rounded-panel bg-card p-12 text-center ring-1 ring-line"><p class="text-5xl">📦</p><h2 class="mt-4 text-xl font-bold text-navy">No orders yet</h2><p class="mt-2 text-muted">When you place an order, it will appear here.</p><button onclick={() => navigate('/products')} class="mt-6 rounded-xl bg-primary px-5 py-3 font-semibold text-white">Shop products</button></div>{/each}</div></section>
